1	// Package server exposes the frozen public surface of SignalWatch.
2	//
3	// Besides the baseline process health check, the server accepts in-memory
4	// metric samples at /api/v1/metrics. All new responses use JSON. Metric state
5	// is process-local and is lost on restart.
6	package server
7	
8	import (
9		"bytes"
10		"encoding/json"
11		"io"
12		"math"
13		"mime"
14		"net/http"
15		"net/url"
16		"regexp"
17		"sort"
18		"strconv"
19		"strings"
20		"sync"
21	)
22	
23	// Version is the baseline release identifier.
24	const Version = "0.1.0"
25	
26	const metricsPath = "/api/v1/metrics"
27	
28	var identPattern = regexp.MustCompile(`^[a-zA-Z_][a-zA-Z0-9_]*$`)
29	
30	type health struct {
31		Status  string `json:"status"`
32		Service string `json:"service"`
33		Version string `json:"version"`
34	}
35	
36	// series is one uniquely identified time series: name + full label set.
37	type series struct {
38		name   string
39		typ    string
40		labels map[string]string
41	
42		// counter/gauge state
43		value float64
44	
45		// histogram state
46		bucketBounds []float64 // strictly increasing, fixed at first write
47		bucketCounts []int64   // cumulative counts per bound, len == len(bucketBounds)
48		count        int64
49		sum          float64
50	}
51	
52	type metricStore struct {
53		mu     sync.RWMutex
54		series map[string]*series
55	
56		// alert rules keyed by rule id; guarded by mu so rule replacement and
57		// alert evaluation are atomic with metric commits.
58		rules map[string]*alertRule
59	
60		// silences keyed by silence id; same lock so alert evaluation reads
61		// metrics, rules and silences from one consistent snapshot.
62		silences map[string]*silence
63	
64		// inhibit rules keyed by rule id; same lock so alert evaluation also
65		// reads inhibit rules from the same consistent snapshot.
66		inhibitions map[string]*inhibitRule
67	
68		// notification routes keyed by route id; same lock so the notification
69		// plan reads routes from the same snapshot as alert evaluation.
70		notificationRoutes map[string]*notificationRoute
71	
72		// SLO definitions keyed by SLO id; same lock so status evaluation reads
73		// definitions and counters from one consistent snapshot.
74		slos map[string]*sloDefinition
75	
76		// Log entries keyed by entry id; same lock so log commits and retrieval
77		// read one consistent snapshot. logOrder is the submission-order FIFO
78		// of ids used for eviction; logSeq is the commit sequence that anchors
79		// paginated read snapshots.
80		logs     map[string]*logEntry
81		logOrder []string
82		logSeq   int64
83	
84		// Spans keyed by tenant-unique "trace_id\x00span_id"; same lock so span
85		// commits and trace reads share the logs snapshot they join against.
86		spans map[string]*span
87	}
88	
89	func newMetricStore() *metricStore {
90		return &metricStore{
91			series:             make(map[string]*series),
92			rules:              make(map[string]*alertRule),
93			silences:           make(map[string]*silence),
94			inhibitions:        make(map[string]*inhibitRule),
95			notificationRoutes: make(map[string]*notificationRoute),
96			slos:               make(map[string]*sloDefinition),
97			logs:               make(map[string]*logEntry),
98			spans:              make(map[string]*span),
99		}
100	}
101	
102	// validatedSample is a sample that passed all format and value checks.
103	type validatedSample struct {
104		key     string
105		name    string
106		typ     string
107		labels  map[string]string
108		value   float64
109		buckets []float64 // non-nil for histograms
110	}
111	
112	// checkAndApply validates the batch against the current state (and against
113	// itself) and then commits it in array order. A false result signals a type or
114	// bucket-boundary conflict; in that case no state is mutated.
115	func (s *metricStore) checkAndApply(batch []validatedSample) bool {
116		s.mu.Lock()
117		defer s.mu.Unlock()
118	
119		// First pass: conflict detection against committed state and earlier
120		// samples in the same batch.
121		resolved := make(map[string]*series, len(batch))
122		for _, sm := range batch {
123			existing, ok := s.series[sm.key]
124			if !ok {
125				if shadow, seen := resolved[sm.key]; seen {
126					existing, ok = shadow, true
127				}
128			}
129			if ok {
130				if existing.typ != sm.typ {
131					return false
132				}
133				if sm.typ == "histogram" && !equalBuckets(existing.bucketBounds, sm.buckets) {
134					return false
135				}
136				resolved[sm.key] = existing
137				continue
138			}
139			resolved[sm.key] = &series{typ: sm.typ, bucketBounds: sm.buckets}
140		}
141	
142		// Second pass: commit in order.
143		for _, sm := range batch {
144			cur, ok := s.series[sm.key]
145			if !ok {
146				cur = &series{
147					name:         sm.name,
148					typ:          sm.typ,
149					labels:       sm.labels,
150					bucketBounds: append([]float64(nil), sm.buckets...),
151				}
152				if sm.typ == "histogram" {
153					cur.bucketCounts = make([]int64, len(sm.buckets))
154				}
155				s.series[sm.key] = cur
156			}
157			switch sm.typ {
158			case "counter":
159				cur.value += sm.value
160			case "gauge":
161				cur.value = sm.value
162			case "histogram":
163				cur.count++
164				cur.sum += sm.value
165				for i, bound := range cur.bucketBounds {
166					if sm.value <= bound {
167						cur.bucketCounts[i]++
168					}
169				}
170			}
171		}
172		return true
173	}
174	
175	type seriesOutput struct {
176		Name    string            `json:"name"`
177		Type    string            `json:"type"`
178		Labels  map[string]string `json:"labels"`
179		Value   *float64          `json:"value,omitempty"`
180		Count   *int64            `json:"count,omitempty"`
181		Sum     *float64          `json:"sum,omitempty"`
182		Buckets []bucketOutput    `json:"buckets,omitempty"`
183	}
184	
185	type bucketOutput struct {
186		LE    float64 `json:"le"`
187		Count int64   `json:"count"`
188	}
189	
190	// query returns matching series as ready-to-encode outputs. A series matches
191	// when its name equals name exactly and it contains every selector label.
192	func (s *metricStore) query(name string, selector map[string]string) []seriesOutput {
193		s.mu.RLock()
194		defer s.mu.RUnlock()
195	
196		out := make([]seriesOutput, 0)
197		for _, cur := range s.series {
198			if cur.name != name {
199				continue
200			}
201			matched := true
202			for k, v := range selector {
203				got, ok := cur.labels[k]
204				if !ok || got != v {
205					matched = false
206					break
207				}
208			}
209			if !matched {
210				continue
211			}
212			item := seriesOutput{
213				Name:   cur.name,
214				Type:   cur.typ,
215				Labels: copyLabels(cur.labels),
216			}
217			switch cur.typ {
218			case "counter", "gauge":
219				v := cur.value
220				item.Value = &v
221			case "histogram":
222				c, sum := cur.count, cur.sum
223				item.Count = &c
224				item.Sum = &sum
225				item.Buckets = make([]bucketOutput, len(cur.bucketBounds))
226				for i, bound := range cur.bucketBounds {
227					item.Buckets[i] = bucketOutput{LE: bound, Count: cur.bucketCounts[i]}
228				}
229			}
230			out = append(out, item)
231		}
232	
233		sort.Slice(out, func(i, j int) bool {
234			return compareLabels(out[i].Labels, out[j].Labels) < 0
235		})
236		return out
237	}
238	
239	// compareLabels imposes a normalized lexicographic order on full label sets:
240	// keys are sorted, then (key, value) pairs are compared element-wise, and a
241	// shorter pair list sorts first when it is a prefix of a longer one.
242	func compareLabels(a, b map[string]string) int {
243		ka := sortedKeys(a)
244		kb := sortedKeys(b)
245		n := len(ka)
246		if len(kb) < n {
247			n = len(kb)
248		}
249		for i := 0; i < n; i++ {
250			if ka[i] != kb[i] {
251				return strings.Compare(ka[i], kb[i])
252			}
253			if a[ka[i]] != b[kb[i]] {
254				return strings.Compare(a[ka[i]], b[kb[i]])
255			}
256		}
257		switch {
258		case len(ka) < len(kb):
259			return -1
260		case len(ka) > len(kb):
261			return 1
262		default:
263			return 0
264		}
265	}
266	
267	func sortedKeys(m map[string]string) []string {
268		keys := make([]string, 0, len(m))
269		for k := range m {
270			keys = append(keys, k)
271		}
272		sort.Strings(keys)
273		return keys
274	}
275	
276	func copyLabels(in map[string]string) map[string]string {
277		out := make(map[string]string, len(in))
278		for k, v := range in {
279			out[k] = v
280		}
281		return out
282	}
283	
284	// seriesKey builds a collision-free identity from name + unordered labels.
285	// Name and label keys are restricted to [a-zA-Z0-9_] and cannot contain NUL,
286	// so length-prefixed values remove any ambiguity from arbitrary label values.
287	func seriesKey(name string, labels map[string]string) string {
288		var b strings.Builder
289		b.WriteString(name)
290		for _, k := range sortedKeys(labels) {
291			b.WriteByte(0)
292			b.WriteString(k)
293			b.WriteByte(0)
294			v := labels[k]
295			b.WriteString(strconv.Itoa(len(v)))
296			b.WriteByte(0)
297			b.WriteString(v)
298		}
299		return b.String()
300	}
301	
302	func equalBuckets(a, b []float64) bool {
303		if len(a) != len(b) {
304			return false
305		}
306		for i := range a {
307			if a[i] != b[i] {
308				return false
309			}
310		}
311		return true
312	}
313	
314	// Handler returns the HTTP surface served by SignalWatch.
315	func Handler() http.Handler {
316		return newHandler(newTenantRegistry())
317	}
318	
319	func newHandler(registry *tenantRegistry) http.Handler {
320		mux := http.NewServeMux()
321	
322		mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
323			if r.Method != http.MethodGet {
324				w.Header().Set("Allow", http.MethodGet)
325				http.Error(w, `{"error":{"code":"method_not_allowed"}}`, http.StatusMethodNotAllowed)
326				return
327			}
328			w.Header().Set("Content-Type", "application/json; charset=utf-8")
329			_ = json.NewEncoder(w).Encode(health{Status: "ok", Service: "signalwatch", Version: Version})
330		})
331	
332		mux.HandleFunc(metricsPath, func(w http.ResponseWriter, r *http.Request) {
333			switch r.Method {
334			case http.MethodGet:
335				handleMetricsGet(w, r)
336			case http.MethodPost:
337				handleMetricsPost(w, r)
338			default:
339				w.Header().Set("Allow", "GET, POST")
340				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
341			}
342		})
343	
344		registerAlertHandlers(mux)
345		registerSilenceHandlers(mux)
346		registerInhibitHandlers(mux)
347		registerNotificationRouteHandlers(mux)
348		registerSLOHandlers(mux)
349		registerQueryHandler(mux)
350		registerLogHandlers(mux)
351		registerSpanHandlers(mux)
352	
353		return withTenants(mux, registry)
354	}
355	
356	func handleMetricsPost(w http.ResponseWriter, r *http.Request) {
357		store := tenantStore(r)
358		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
359		if err != nil || mediaType != "application/json" {
360			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
361			return
362		}
363	
364		body, err := io.ReadAll(r.Body)
365		if err != nil {
366			writeAPIError(w, "invalid_metrics", http.StatusBadRequest)
367			return
368		}
369	
370		batch, ok := decodeMetricsBatch(body)
371		if !ok {
372			writeAPIError(w, "invalid_metrics", http.StatusBadRequest)
373			return
374		}
375	
376		if !store.checkAndApply(batch) {
377			writeAPIError(w, "metric_conflict", http.StatusConflict)
378			return
379		}
380	
381		w.Header().Set("Content-Type", "application/json; charset=utf-8")
382		w.WriteHeader(http.StatusAccepted)
383		_ = json.NewEncoder(w).Encode(map[string]int{"accepted": len(batch)})
384	}
385	
386	type metricsEnvelope struct {
387		Samples *[]json.RawMessage `json:"samples"`
388	}
389	
390	type rawSample struct {
391		Name    *string            `json:"name"`
392		Type    *string            `json:"type"`
393		Labels  *map[string]string `json:"labels"`
394		Value   *float64           `json:"value"`
395		Buckets *[]float64         `json:"buckets"`
396	}
397	
398	// decodeMetricsBatch performs every format and value check. It never returns a
399	// partially validated batch.
400	func decodeMetricsBatch(body []byte) ([]validatedSample, bool) {
401		var env metricsEnvelope
402		if !strictDecode(body, &env) || env.Samples == nil || len(*env.Samples) == 0 {
403			return nil, false
404		}
405	
406		batch := make([]validatedSample, 0, len(*env.Samples))
407		for _, raw := range *env.Samples {
408			var sm rawSample
409			if !strictDecode(raw, &sm) {
410				return nil, false
411			}
412			if sm.Name == nil || sm.Type == nil || sm.Labels == nil || sm.Value == nil {
413				return nil, false
414			}
415			name, typ := *sm.Name, *sm.Type
416			if !identPattern.MatchString(name) {
417				return nil, false
418			}
419			if typ != "counter" && typ != "gauge" && typ != "histogram" {
420				return nil, false
421			}
422			labels := *sm.Labels
423			if labels == nil {
424				return nil, false // explicit null labels
425			}
426			for k := range labels {
427				if !identPattern.MatchString(k) {
428					return nil, false
429				}
430			}
431			value := *sm.Value
432			if math.IsNaN(value) || math.IsInf(value, 0) {
433				return nil, false // encoding/json already rejects NaN/Inf tokens
434			}
435			if typ == "counter" && value < 0 {
436				return nil, false
437			}
438	
439			var buckets []float64
440			if typ == "histogram" {
441				if sm.Buckets == nil || !validBuckets(*sm.Buckets) {
442					return nil, false
443				}
444				buckets = append([]float64(nil), (*sm.Buckets)...)
445			} else if sm.Buckets != nil {
446				return nil, false // buckets only valid on histograms
447			}
448	
449			batch = append(batch, validatedSample{
450				key:     seriesKey(name, labels),
451				name:    name,
452				typ:     typ,
453				labels:  copyLabels(labels),
454				value:   value,
455				buckets: buckets,
456			})
457		}
458		return batch, true
459	}
460	
461	func validBuckets(buckets []float64) bool {
462		if len(buckets) == 0 {
463			return false
464		}
465		prev := math.Inf(-1)
466		for _, b := range buckets {
467			if math.IsNaN(b) || math.IsInf(b, 0) || b <= prev {
468				return false
469			}
470			prev = b
471		}
472		return true
473	}
474	
475	// strictDecode decodes JSON, rejecting unknown fields, multiple/ trailing
476	// values and non-object payloads for struct targets.
477	func strictDecode(data []byte, target any) bool {
478		dec := json.NewDecoder(bytes.NewReader(data))
479		dec.DisallowUnknownFields()
480		if err := dec.Decode(target); err != nil {
481			return false
482		}
483		var extra json.RawMessage
484		if err := dec.Decode(&extra); err != io.EOF {
485			return false
486		}
487		return true
488	}
489	
490	func handleMetricsGet(w http.ResponseWriter, r *http.Request) {
491		store := tenantStore(r)
492		values, err := url.ParseQuery(r.URL.RawQuery)
493		if err != nil {
494			writeAPIError(w, "invalid_query", http.StatusBadRequest)
495			return
496		}
497	
498		names := values["name"]
499		if len(names) == 0 || !identPattern.MatchString(names[0]) {
500			writeAPIError(w, "invalid_query", http.StatusBadRequest)
501			return
502		}
503	
504		selector := make(map[string]string)
505		for key, vals := range values {
506			if !strings.HasPrefix(key, "label.") {
507				continue
508			}
509			labelKey := strings.TrimPrefix(key, "label.")
510			if !identPattern.MatchString(labelKey) {
511				writeAPIError(w, "invalid_query", http.StatusBadRequest)
512				return
513			}
514			for _, v := range vals[1:] {
515				if v != vals[0] {
516					writeAPIError(w, "invalid_query", http.StatusBadRequest)
517					return
518				}
519			}
520			selector[labelKey] = vals[0]
521		}
522	
523		seriesList := store.query(names[0], selector)
524		w.Header().Set("Content-Type", "application/json; charset=utf-8")
525		_ = json.NewEncoder(w).Encode(map[string]any{"series": seriesList})
526	}
527	
528	func writeAPIError(w http.ResponseWriter, code string, status int) {
529		w.Header().Set("Content-Type", "application/json; charset=utf-8")
530		w.WriteHeader(status)
531		_ = json.NewEncoder(w).Encode(map[string]any{"error": map[string]string{"code": code}})
532	}
533

