26		"avg": true,
27		"min": true,
28		"max": true,
29	}
30	
31	// ---- expression parser -----------------------------------------------------
32	
33	type exprParser struct {
34		s string
35		p int
36	}
37	
38	// parseQueryExpr parses the single expression accepted by GET /api/v1/query.
39	// Whitespace is ASCII only and may surround any punctuation or keyword. The
40	// grammar:
41	//
42	//	expr        := selector | aggregation
43	//	aggregation := ident ("by" "(" ident ("," ident)* ")")? "(" selector ")"
44	//	selector    := ident "{" (ident "=" jsonString ("," ident "=" jsonString)*)? "}"
45	//
46	// The aggregation identifier must be one of sum/avg/min/max. Duplicate
47	// matchers or grouping labels, nested aggregations, unknown functions and any
48	// trailing input are rejected.
49	func parseQueryExpr(in string) (*queryExpr, bool) {
50		p := &exprParser{s: in}
51		p.skipSpaces()
52	
53		word, ok := p.parseIdent()
54		if !ok {
55			return nil, false
56		}
57		p.skipSpaces()
58	
59		e := &queryExpr{}
