61		// call ("(" or a by clause); followed by "{" it is simply a metric named
62		// like the keyword (metric writes impose no such reservation).
63		if queryAggregates[word] && (p.next() == '(' || p.hasIdent("by")) {
64			e.aggregate = word
65			if p.hasIdent("by") {
66				p.p += 2
67				p.skipSpaces()
68				if !p.expect('(') {
69					return nil, false
70				}
71				seen := make(map[string]bool)
72				for {
73					p.skipSpaces()
74					label, ok := p.parseIdent()
75					if !ok {
76						return nil, false
77					}
78					if seen[label] {
79						return nil, false
80					}
81					seen[label] = true
82					e.by = append(e.by, label)
83					p.skipSpaces()
84					switch p.next() {
85					case ',':
86						p.p++
87						continue
88					case ')':
89						p.p++
90					default:
91						return nil, false
92					}
93					break
