137		}
138		return p.parseMatcherListInto(e)
139	}
140	
141	// parseMatcherListInto parses matcher-list "}" with the opening "{" consumed.
142	func (p *exprParser) parseMatcherListInto(e *queryExpr) bool {
143		e.selector = make(map[string]string)
144		p.skipSpaces()
145		if p.next() == '}' {
146			p.p++
147			return true
148		}
149		for {
150			p.skipSpaces()
151			key, ok := p.parseIdent()
152			if !ok {
153				return false
154			}
155			if _, dup := e.selector[key]; dup {
156				return false
157			}
158			p.skipSpaces()
159			if !p.expect('=') {
160				return false
161			}
162			p.skipSpaces()
163			value, ok := p.parseJSONString()
164			if !ok {
165				return false
166			}
167			e.selector[key] = value
168			p.skipSpaces()
169			switch p.next() {
170			case ',':
171				p.p++
172				continue
173			case '}':
174				p.p++
175				return true
176			default:
177				return false
178			}
179		}
180	}
181	
182	func (p *exprParser) next() byte {
183		if p.p >= len(p.s) {
184			return 0
185		}
186		return p.s[p.p]
187	}
188	
189	func (p *exprParser) expect(c byte) bool {
190		if p.next() != c {
191			return false
192		}
193		p.p++
194		return true
195	}
196	
197	func (p *exprParser) skipSpaces() {
