215	// parseIdent consumes an identifier matching identPattern and reports whether
216	// one was present.
217	func (p *exprParser) parseIdent() (string, bool) {
218		start := p.p
219		if p.p >= len(p.s) || !isIdentStart(p.s[p.p]) {
220			return "", false
