320			sort.Slice(out, func(i, j int) bool {
321				return compareLabels(out[i].Labels, out[j].Labels) < 0
322			})
323			return out, true
324		}
325	
326		type groupAcc struct {
327			labels map[string]string
328			value  float64
329			count  int
330		}
331		groups := make(map[string]*groupAcc)
